import "../src/timed_crowdsale.sol";
import {Test} from "forge-std/Test.sol";

contract TimedCrowdsaleTest is Test {
    TimedCrowdsale public crowdsale;
    address public owner;
    address public contributor;

    uint256 public constant FINISH_TIMESTAMP = 1546300800;
    uint256 public constant ONE_DAY = 86400;
    uint256 public constant PRE_FINISH_TIME = FINISH_TIMESTAMP - 1;
    uint256 public contributionAmount = 1 ether;

    function setUp() public {
        crowdsale = new TimedCrowdsale();
        owner = address(this); // Test contract is deployer/owner
        contributor = address(0x1);
        vm.deal(contributor, 10 ether);
    }

    // Add receive function to accept withdrawal transfers
    receive() external payable {}

    function test_timestampManipulation() public {
        // Advance to 1 second before finish time
        vm.warp(PRE_FINISH_TIME);
        assertFalse(crowdsale.isSaleFinished(), "Sale finished unexpectedly");

        // Store initial owner balance
        uint256 initialOwnerBalance = address(this).balance;

        // Contribute while sale is active
        vm.prank(contributor);
        crowdsale.contribute{value: contributionAmount}();
        assertEq(
            address(crowdsale).balance,
            contributionAmount,
            "Failed to capture contribution"
        );

        // Immediately attempt owner withdrawal (should fail)
        vm.expectRevert();
        crowdsale.withdrawFunds();

        // ============ DIFFERENTIAL VERIFICATION START =============
        console.log("--- BEFORE-Trigger Timestamp Warp ---");
        uint256 contractBalanceBefore = address(crowdsale).balance;
        uint256 contributorContributionBefore = crowdsale.contributions(contributor);
        uint256 totalContributionsBefore = crowdsale.totalContributions();

        console.log("Contract Balance:", contractBalanceBefore);
        console.log("Contributor's Contribution:", contributorContributionBefore);
        console.log("Total Contributions:", totalContributionsBefore);

        console.log("--- TRIGGER: Time Warp to FINISH_TIMESTAMP ---");
        vm.warp(FINISH_TIMESTAMP);
        console.log("--- AFTER-Trigger Timestamp Warp ---");

        uint256 contractBalanceAfter = address(crowdsale).balance;
        uint256 contributorContributionAfter = crowdsale.contributions(contributor);
        uint256 totalContributionsAfter = crowdsale.totalContributions();

        console.log("Contract Balance:", contractBalanceAfter);
        console.log("Contributor's Contribution:", contributorContributionAfter);
        console.log("Total Contributions:", totalContributionsAfter);

        // Compare state changes
        bool stateChanged = 
            contractBalanceBefore != contractBalanceAfter ||
            contributorContributionBefore != contributorContributionAfter ||
            totalContributionsBefore != totalContributionsAfter;

        console.log("State Consistent During Warp?", stateChanged ? "NO" : "YES");
        // ============ DIFFERENTIAL VERIFICATION END =============

        assertTrue(crowdsale.isSaleFinished(), "Sale did not finish");

        // Owner withdrawals now possible
        crowdsale.withdrawFunds();
        assertEq(
            address(crowdsale).balance,
            0,
            "Failed to withdraw funds"
        );
        assertEq(
            address(this).balance,
            initialOwnerBalance + contributionAmount,
            "Owner did not receive funds"
        );

        // Attempt contribution after sale finish
        vm.prank(contributor);
        vm.expectRevert();
        crowdsale.contribute{value: contributionAmount}();

        // Final vulnerability verdict
        if (stateChanged) {
            console.log("Vulnerability Exists: Financial state altered during timestamp warp");
        } else {
            console.log("Vulnerability not Exist: Contract state remains consistent during timestamp manipulation");
        }
    }

    function test_boundaryTimestampControl() public {
        // Demonstrate control over boundary conditions
        vm.warp(FINISH_TIMESTAMP - ONE_DAY);
        assertFalse(crowdsale.isSaleFinished(), "Sale finished too early");

